      h: item.size.h * 16   // tileH
    }
  }));

  worldA.forEach(machine => {
    if (machine.id === "ipcamA") {
      machine.status = "active";
    }
  });

  setVar("worldA", worldA);
  setVar("worldA_iso", isoPositions);

  return {
    status: 'rendered'
  };
}

