async function processRequest(input) {
  const worldA = getVar("worldA") || [];

  let worldItem = worldA.find(m => m.id === "world");
  if (!worldItem) {
    worldItem = {
      id: "world",
      name: "world",
      position: { x: 0, y: 0, z: 0 },
      size: { w: 5, h: 5, d: 1 },
      imageurl: "https://aiagent.maxsolo.co.uk/images/virualspace_b.png",
      zIndex: 0,
      status: "idle",
dialogue: {
        text: "歡迎來到這台工業設備的控制室。"
      }
    };
    worldA.push(worldItem);
  } else {
    if (!worldItem.hasOwnProperty("zIndex")) {
      worldItem.zIndex = 0;
    }
  }


  setVar("worldA", worldA);

  const tileSize = 64;

  let clientJS = `
    (function() {
      const tileSize = ${tileSize};
      const outputBody = document.getElementById('output-body');
      if (!outputBody) return;

      const worldA = ${JSON.stringify(worldA)};

      // Step 1: add / update elements
      worldA.forEach(function(item) {
        var el = document.getElementById(item.id);
        if (!el) {
          el = document.createElement('div');
          el.id = item.id;
          el.style.position = 'absolute';
          el.style.border = '1px solid #000';
          if (item.imageurl) {
            el.style.backgroundImage = 'url(' + item.imageurl + ')';
            el.style.backgroundSize = '100% 100%';
            el.style.backgroundPosition = 'center';
          } else {
            el.style.backgroundColor = (item.color || 'rgba(255, 255, 255, 0.5)');
          }

          if (item.zIndex === undefined) {
            el.style.zIndex = 1;
          } else {
            el.style.zIndex = item.zIndex;
          }
          outputBody.appendChild(el);
        }

        el.style.left = (item.position.x * tileSize) + 'px';
        el.style.top = (item.position.y * tileSize) + 'px';
        el.style.width = (item.size.w * tileSize) + 'px';
        el.style.height = (item.size.h * tileSize) + 'px';

        var label = el.querySelector('.label');
        if (!label) {
          label = document.createElement('div');
          label.className = 'label';
          label.style.position = 'absolute';
          label.style.bottom = '0';
          label.style.left = '0';
          label.style.background = 'rgba(0,0,0,0.7)';
          label.style.color = 'white';
          label.style.fontSize = '10px';
          label.style.padding = '2px';
          el.appendChild(label);
        }
        label.textContent = item.name || item.id;

        // === Dialogue：長期顯示在物件旁邊（下方） ===
        // 清除舊的 dialogue element
        var oldDlg = el.querySelector('.dialogue-text');
        if (oldDlg) oldDlg.remove();

        if (item.dialogue && item.dialogue.text) {
          var dlg = document.createElement('div');
          dlg.className = 'dialogue-text';
          dlg.style.position = 'absolute';
          dlg.style.top = '100%';          // 在物件下方
          dlg.style.left = '0';
          dlg.style.marginTop = '2px';
          dlg.style.background = 'rgba(0, 0, 0, 0.7)';
          dlg.style.color = 'white';
          dlg.style.fontSize = '10px';
          dlg.style.padding = '2px 4px';
          dlg.style.whiteSpace = 'nowrap';
          dlg.textContent = item.dialogue.text;
          el.appendChild(dlg);
        }
      });

      // Step 2: remove elements not in worldA
      var worldIds = worldA.map(function(i){ return i.id; });
      var allEls = Array.prototype.slice.call(
        outputBody.querySelectorAll('div[id]')
      );
      allEls.forEach(function(el) {
        if (worldIds.indexOf(el.id) === -1) {
          el.remove();
        }
      });
    })();
  `;

  return {
    status: "ready",
    clientJS,
  };
}

